package cn.voidhaven.api.service;
import cn.voidhaven.api.domain.*;
import cn.voidhaven.api.persistence.*;
import cn.voidhaven.api.support.Ids;
import cn.voidhaven.api.web.ApiException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.ObjectMapper;
import java.util.*;

@Service
public class ContentManagementService {
    private final ContentItemRepository items; private final ContentRevisionRepository revisions; private final PartnerProfileRepository profiles; private final AuditService audit; private final ObjectMapper mapper; private final ContentSourcePolicy sources; private final RichTextPolicy richText;
    public ContentManagementService(ContentItemRepository items, ContentRevisionRepository revisions, PartnerProfileRepository profiles, AuditService audit, ObjectMapper mapper, ContentSourcePolicy sources, RichTextPolicy richText) { this.items = items; this.revisions = revisions; this.profiles = profiles; this.audit = audit; this.mapper = mapper; this.sources = sources; this.richText = richText; }
    public record Draft(String kind, String title, String summary, JsonNode body, String languageCode, String sourceUrl, String sourceName, String rightsBasis, JsonNode details) { }
    public record Managed(String id, ContentKind kind, WorkflowStatus workflowStatus, PublicationStatus publicationStatus, Visibility visibility, RecordState recordState, String title, long revision) { }
    public record Editable(String id, Draft draft, long revision, WorkflowStatus workflowStatus, Visibility visibility, RecordState recordState) { }
    @Transactional public Managed create(Draft draft, String ownerProfileId, String actorId, String role, String requestId) {
        ContentKind kind = parseKind(draft.kind()); validate(draft, kind); ContentItem item = new ContentItem(Ids.ulid(), kind, WorkflowStatus.DRAFT, Visibility.HIDDEN, RecordState.ACTIVE); item.setOwnerPartnerProfileId(ownerProfileId); item = items.saveAndFlush(item);
        ContentRevision revision = new ContentRevision(Ids.ulid(), item, 1, draft.title().trim(), draft.summary().trim(), json(draft.body()), draft.languageCode().trim(), draft.sourceUrl().trim(), draft.sourceName().trim(), draft.rightsBasis().trim(), json(draft.details()), actorId); revision = revisions.saveAndFlush(revision); item.setCurrentRevision(revision); item = items.saveAndFlush(item); audit.record(actorId, role, "CONTENT_CREATED", "CONTENT_ITEM", item.getId(), "{}", "{\"workflowStatus\":\"DRAFT\"}", null, requestId); return managed(item);
    }
    @Transactional public Managed submit(String id, String ownerProfileId, String actorId, String role, String requestId) { ContentItem item = owned(id, ownerProfileId); require(item.getWorkflowStatus() == WorkflowStatus.DRAFT || item.getWorkflowStatus() == WorkflowStatus.CHANGES_REQUESTED, "CONTENT_NOT_SUBMITTABLE"); item.submit(); audit.record(actorId, role, "CONTENT_SUBMITTED", "CONTENT_ITEM", id, "{\"workflowStatus\":\"DRAFT\"}", "{\"workflowStatus\":\"PENDING_REVIEW\"}", null, requestId); return managed(item); }
    @Transactional public Managed submitAsAdmin(String id, String actorId, String role, String requestId) { ContentItem item = find(id); require(item.getWorkflowStatus() == WorkflowStatus.DRAFT || item.getWorkflowStatus() == WorkflowStatus.CHANGES_REQUESTED, "CONTENT_NOT_SUBMITTABLE"); item.submit(); audit.record(actorId, role, "CONTENT_SUBMITTED", "CONTENT_ITEM", id, "{\"workflowStatus\":\"DRAFT\"}", "{\"workflowStatus\":\"PENDING_REVIEW\"}", null, requestId); return managed(item); }
    @Transactional public Managed revise(String id, Draft draft, String ownerProfileId, Long expectedVersion, String actorId, String role, String requestId) {
        ContentItem item = ownerProfileId == null ? find(id) : owned(id, ownerProfileId);
        if (expectedVersion == null || !Objects.equals(item.getVersion(), expectedVersion)) throw new ApiException(HttpStatus.CONFLICT, "CONTENT_VERSION_CONFLICT", "内容已被其他操作更新，请刷新后再编辑。");
        require(item.getRecordState() == RecordState.ACTIVE, "CONTENT_NOT_EDITABLE");
        require(item.getWorkflowStatus() == WorkflowStatus.DRAFT || item.getWorkflowStatus() == WorkflowStatus.CHANGES_REQUESTED || item.getWorkflowStatus() == WorkflowStatus.PUBLISHED, "CONTENT_NOT_EDITABLE");
        ContentKind kind = parseKind(draft.kind());
        if (kind != item.getKind()) throw new ApiException(HttpStatus.BAD_REQUEST, "CONTENT_KIND_IMMUTABLE", "已创建内容不能变更栏目类型。");
        validate(draft, kind);
        int nextRevision = item.getCurrentRevision().getRevisionNumber() + 1;
        ContentRevision revision = new ContentRevision(Ids.ulid(), item, nextRevision, draft.title().trim(), draft.summary().trim(), json(draft.body()), draft.languageCode().trim(), draft.sourceUrl().trim(), draft.sourceName().trim(), draft.rightsBasis().trim(), json(draft.details()), actorId);
        revision = revisions.saveAndFlush(revision);
        item.setCurrentRevision(revision);
        item.beginCandidateRevision();
        item = items.saveAndFlush(item);
        audit.record(actorId, role, "CONTENT_REVISION_CREATED", "CONTENT_ITEM", id, "{\"revision\":" + (nextRevision - 1) + "}", "{\"revision\":" + nextRevision + ",\"workflowStatus\":\"DRAFT\"}", null, requestId);
        return managed(item);
    }
    @Transactional public Managed decide(String id, String decision, String reason, String actorId, String role, String requestId) { ContentItem item = find(id); require(item.getWorkflowStatus() == WorkflowStatus.PENDING_REVIEW, "CONTENT_NOT_IN_REVIEW"); String before = "{\"workflowStatus\":\"PENDING_REVIEW\"}"; if ("APPROVE".equals(decision)) item.approve(); else if ("CHANGES_REQUESTED".equals(decision)) item.requestChanges(); else if ("REJECT".equals(decision)) item.reject(); else throw new ApiException(HttpStatus.BAD_REQUEST, "INVALID_REVIEW_DECISION", "审核决定无效。"); audit.recordReview(item.getId(), item.getCurrentRevision().getId(), actorId, decision, reason); audit.record(actorId, role, "REVIEW_" + decision, "CONTENT_ITEM", id, before, "{\"workflowStatus\":\"" + item.getWorkflowStatus() + "\"}", reason, requestId); return managed(item); }
    @Transactional public Managed publish(String id, String actorId, String role, String requestId) { ContentItem item = items.findByIdForUpdate(id).orElseThrow(() -> new ApiException(HttpStatus.NOT_FOUND, "CONTENT_NOT_FOUND", "内容不存在。")); require(item.getWorkflowStatus() == WorkflowStatus.APPROVED, "CONTENT_NOT_APPROVED"); if (item.getOwnerPartnerProfileId() != null) { PartnerProfile profile = profiles.findByIdForUpdate(item.getOwnerPartnerProfileId()).orElseThrow(() -> new ApiException(HttpStatus.CONFLICT, "PARTNER_PROFILE_INACTIVE", "内容归属合作方当前不可用。")); require(profile.isActive(), "PARTNER_PROFILE_INACTIVE"); long active = items.countPublicActiveByOwnerPartnerProfileId(profile.getId()); boolean alreadyPublic = item.getPublishedRevision() != null && item.getVisibility() == Visibility.PUBLIC && item.getRecordState() == RecordState.ACTIVE; if (!alreadyPublic && active >= profile.getContentQuota()) throw new ApiException(HttpStatus.CONFLICT, "PARTNER_QUOTA_EXCEEDED", "该合作方的公开活跃内容已达到配额。"); } item.publish(); audit.record(actorId, role, "CONTENT_PUBLISHED", "CONTENT_ITEM", id, "{\"visibility\":\"HIDDEN\"}", "{\"visibility\":\"PUBLIC\"}", null, requestId); return managed(item); }
    @Transactional public Managed hide(String id, String reason, String actorId, String role, String requestId) { ContentItem item = find(id); item.hide(); audit.record(actorId, role, "CONTENT_HIDDEN", "CONTENT_ITEM", id, "{}", "{\"visibility\":\"HIDDEN\"}", reason, requestId); return managed(item); }
    @Transactional public Managed show(String id, String actorId, String role, String requestId) { ContentItem item = find(id); require(item.getPublishedRevision() != null && item.getPublicationStatus() != PublicationStatus.NONE && item.getRecordState() == RecordState.ACTIVE && item.getVisibility() == Visibility.HIDDEN, "CONTENT_NOT_SHOWABLE"); item.show(); audit.record(actorId, role, "CONTENT_SHOWN", "CONTENT_ITEM", id, "{\"visibility\":\"HIDDEN\"}", "{\"visibility\":\"PUBLIC\"}", null, requestId); return managed(item); }
    @Transactional public Managed archive(String id, String reason, String actorId, String role, String requestId) { ContentItem item = find(id); item.archive(); audit.record(actorId, role, "CONTENT_ARCHIVED", "CONTENT_ITEM", id, "{}", "{\"recordState\":\"ARCHIVED\"}", reason, requestId); return managed(item); }
    @Transactional public Managed restore(String id, String reason, String actorId, String role, String requestId) { ContentItem item = find(id); require(item.getRecordState() == RecordState.ARCHIVED, "CONTENT_NOT_RESTORABLE"); item.restore(); audit.record(actorId, role, "CONTENT_RESTORED", "CONTENT_ITEM", id, "{\"recordState\":\"ARCHIVED\"}", "{\"recordState\":\"ACTIVE\",\"visibility\":\"HIDDEN\",\"workflowStatus\":\"APPROVED\"}", reason, requestId); return managed(item); }
    @Transactional public Managed delete(String id, String reason, String actorId, String role, String requestId) { ContentItem item = find(id); item.markDeleted(); audit.record(actorId, role, "CONTENT_DELETED", "CONTENT_ITEM", id, "{}", "{\"recordState\":\"DELETED\",\"visibility\":\"HIDDEN\"}", reason, requestId); return managed(item); }
    @Transactional(readOnly = true) public List<Managed> pending() { return items.findByWorkflowStatusOrderByIdAsc(WorkflowStatus.PENDING_REVIEW).stream().map(this::managed).toList(); }
    @Transactional(readOnly = true) public List<Managed> allManaged() { return items.findAllByOrderByIdDesc().stream().map(this::managed).toList(); }
    @Transactional(readOnly = true) public List<Managed> ownedList(String profileId) { return items.findByOwnerPartnerProfileIdOrderByIdDesc(profileId).stream().map(this::managed).toList(); }
    @Transactional(readOnly = true) public Editable ownedEditable(String id, String profileId) { ContentItem item = owned(id, profileId); ContentRevision revision = item.getCurrentRevision(); try { return new Editable(item.getId(), new Draft(item.getKind().name(), revision.getTitle(), revision.getSummary(), mapper.readTree(revision.getBodyJson()), revision.getLanguageCode(), revision.getSourceUrl(), revision.getSourceName(), revision.getRightsBasis(), mapper.readTree(revision.getDetailsJson())), item.getVersion() == null ? 0 : item.getVersion(), item.getWorkflowStatus(), item.getVisibility(), item.getRecordState()); } catch (Exception error) { throw new IllegalStateException("Invalid persisted content document", error); } }
    private ContentItem find(String id) { return items.findById(id).orElseThrow(() -> new ApiException(HttpStatus.NOT_FOUND, "CONTENT_NOT_FOUND", "内容不存在。")); }
    private ContentItem owned(String id, String profileId) { ContentItem item = find(id); if (!Objects.equals(item.getOwnerPartnerProfileId(), profileId)) throw new ApiException(HttpStatus.NOT_FOUND, "CONTENT_NOT_FOUND", "内容不存在或当前不可见。"); return item; }
    private void validate(Draft draft, ContentKind kind) { if (blank(draft.title()) || blank(draft.summary()) || blank(draft.sourceUrl()) || blank(draft.sourceName()) || blank(draft.rightsBasis()) || draft.body() == null || draft.details() == null) throw new ApiException(HttpStatus.BAD_REQUEST, "CONTENT_VALIDATION_FAILED", "请补齐标题、导读、正文、来源、权利说明和结构化字段。"); richText.requireAllowed(draft.body()); sources.requireAllowed(draft.sourceUrl()); if (kind == ContentKind.COMPETITION && !draft.details().hasNonNull("officialRulesUrl")) throw new ApiException(HttpStatus.BAD_REQUEST, "OFFICIAL_SOURCE_REQUIRED", "竞赛必须提供可核验的官方规则链接。"); if (kind == ContentKind.COMPETITION) sources.requireAllowed(draft.details().get("officialRulesUrl").asText()); }
    private ContentKind parseKind(String value) { try { return ContentKind.valueOf(value); } catch (Exception e) { throw new ApiException(HttpStatus.BAD_REQUEST, "INVALID_CONTENT_KIND", "内容类型无效。"); } }
    private String json(JsonNode node) { try { return mapper.writeValueAsString(node); } catch (Exception e) { throw new IllegalStateException(e); } }
    private boolean blank(String value) { return value == null || value.isBlank(); }
    private void require(boolean valid, String code) { if (!valid) throw new ApiException(HttpStatus.CONFLICT, code, "当前内容状态不允许此操作。"); }
    private Managed managed(ContentItem item) { return new Managed(item.getId(), item.getKind(), item.getWorkflowStatus(), item.getPublicationStatus(), item.getVisibility(), item.getRecordState(), item.getCurrentRevision().getTitle(), item.getVersion() == null ? 0 : item.getVersion()); }
}
